figures.script:
diagram("direction: right
(New) as n
[Ready] as r #blue
[Running] as x #mint
[Waiting] as w #amber
(Terminated) as t
n -> r : admitted
r -> x : scheduler dispatch
x -> r : time slice over
x -> w : waits for I/O
w -> r : I/O done
x -> t : exit
@0 n -> r : admit
@1.2 r -> x : dispatch
@2.4 x -> w : I/O
@3.6 w -> r : done
@4.8 r -> x : dispatch
@6 x -> t : exit
loop 8");

diagram("mode: sequence
[Shell (parent)] as p
[Kernel] as k
[Child process] as c
p -> k : fork()
k -> c : copy of the shell created (copy-on-write)
k -> p : returns child pid (e.g. 4021)
k -> c : returns 0
c -> k : exec("/bin/ls")
k -> c : memory replaced by ls
c -> c : runs ls, prints files
c -> k : exit(0)
p -> k : wait() returns status 0
@0 p -> k : fork()
@1 k -> c : copy created
@2 k -> p : returns child pid
@3 k -> c : returns 0
@4 c -> k : exec ls
@5 k -> c : image replaced
@6 c -> c : runs ls
@7 c -> k : exit(0)
@8 p -> k : wait() returns
loop 11");

diagram("direction: down
[Queue 0 — RR, q = 8] as q0 #mint
[Queue 1 — RR, q = 16] as q1 #blue
[Queue 2 — FCFS] as q2 #violet
(CPU) as cpu
q0 -> cpu : always first
q1 -> cpu : only if queue 0 empty
q2 -> cpu : only if 0 and 1 empty
q0 -> q1 : used full quantum (demote)
q1 -> q2 : used full quantum (demote)
q2 -> q0 : waited too long (age up)
@0 q0 -> cpu
@1.2 q0 -> q1
@2.4 q1 -> cpu
@3.6 q1 -> q2
@4.8 q2 -> q0
loop 7");

diagram("direction: right
[Runnable tasks] as t #blue
[Red-black tree ordered by virtual runtime] as tree #violet
[Leftmost = smallest vruntime] as left #mint
(Run it for a slice) as run
t -> tree : insert
tree -> left : pick
left -> run
run -> t : vruntime grows, re-insert
@0 t -> tree : task
@1.2 tree -> left : min
@2.4 left -> run : chosen
@3.6 run -> t : re-queued
loop 5");
